102	                    "the picture \"\(asset.name)\" is not a \(GraphicStore.assetKinds) file")
103	            }
104	            guard GraphicAssetName.isLegal(asset.name) else {
105	                throw refuse("the picture \"\(asset.name)\" \(GraphicAssetName.rule)")
106	            }
107	            guard !asset.bytes.isEmpty else {
108	                throw refuse("the picture \"\(asset.name)\" is empty (0 bytes)")
109	            }
110	        }
111	        return GraphicPackageContents(
112	            module: manifest["module"] as? String ?? "", title: manifest["title"] as? String ?? "",
113	            category: manifest["category"] as? String ?? "",
114	            description: manifest["description"] as? String,
115	            appVersion: manifest["app_version"] as? String ?? "", source: bytes(first),
116	            fonts: fonts, assets: assets)
117	    }
118	}
119	
120	/// What an import does with one file.
121	enum GraphicImportAction: String {
122	    case written, reused
123	}
124	
125	/// One file's place: `name` the manifest's, `target` the name on disk.
126	struct GraphicImportPlacement {
127	    let name: String
128	    let target: String
129	    let action: GraphicImportAction
130	}
131	
132	/// Where every file of a package goes in one project, and the copy.
133	struct GraphicImportPlan {
134	    let contents: GraphicPackageContents
135	    let module: GraphicImportPlacement
136	    let fonts: [GraphicImportPlacement]
137	    let assets: [GraphicImportPlacement]
138	
139	    /// G-47 (d) over the store's scan and the disk. Throws, writing nothing, for an asset
140	    /// whose name holds a different picture, or with no store.
141	    static func make(_ contents: GraphicPackageContents, document: ProjectDocument) throws
142	        -> GraphicImportPlan
143	    {
144	        guard let store = document.graphicStore else {
145	            throw ReelCoreError(message: ProjectDocument.noGraphicsFolderSentence)
146	        }
147	        let folder = store.folderURL
148	        let free = { (name: String) in
149	            !store.holdsModule(named: name) && document.graphicClips(named: name).isEmpty
150	        }
151	        let module: GraphicImportPlacement
152	        let held = try? Data(contentsOf: folder.appendingPathComponent(contents.module + ".js"))
153	        if free(contents.module) {
154	            module = .init(name: contents.module, target: contents.module, action: .written)
155	        } else if held == contents.source {
156	            module = .init(name: contents.module, target: contents.module, action: .reused)
157	        } else {
158	            let root = String(String.UnicodeScalarView(contents.module.unicodeScalars.prefix(60)))
159	            var n = 2
160	            while !free("\(root)-\(n)") { n += 1 }
161	            module = .init(name: contents.module, target: "\(root)-\(n)", action: .written)
162	        }
163	        var fonts = Names(folder.appendingPathComponent(GraphicStore.fontsFolderName))
164	        let fontPlaces = contents.fonts.map { font -> GraphicImportPlacement in
165	            var target = font.name
166	            var n = 2
167	            while true {
168	                if let action = fonts.place(target, font.bytes) {
169	                    return .init(name: font.name, target: target, action: action)
170	                }
171	                target = GraphicAssetName.withSuffix(font.name, n)
172	                n += 1
173	            }
174	        }
175	        var assets = Names(folder.appendingPathComponent(GraphicStore.assetsFolderName))
176	        let assetPlaces = try contents.assets.map { asset -> GraphicImportPlacement in
177	            guard let action = assets.place(asset.name, asset.bytes) else {
178	                throw ReelCoreError(
179	                    message: "graphics/assets/\(asset.name) already holds a different picture, "
180	                        + "and this graphic reaches its own by asset(\"\(asset.name)\"), so it "
181	                        + "cannot be renamed; rename or remove the project's file and import "
182	                        + "again")
183	            }
184	            return .init(name: asset.name, target: asset.name, action: action)
185	        }
186	        return GraphicImportPlan(
187	            contents: contents, module: module, fonts: fontPlaces, assets: assetPlaces)
188	    }
189	
190	    /// One folder's names, as the disk holds them and as this plan claims them.
191	    private struct Names {
192	        let folder: URL
193	        var taken: [String]
194	
195	        init(_ folder: URL) {
196	            self.folder = folder
197	            taken = (try? FileManager.default.contentsOfDirectory(atPath: folder.path)) ?? []
198	        }
199	
200	        /// `.written` when `name` is free (and claims it), `.reused` when a file of exactly
201	        /// that name holds `bytes`, nil otherwise — a name that differs only in case is taken.
202	        mutating func place(_ name: String, _ bytes: Data) -> GraphicImportAction? {
203	            let url = folder.appendingPathComponent(name)
204	            if taken.contains(name) {
205	                return (try? Data(contentsOf: url)) == bytes ? .reused : nil
206	            }
207	            let folded = name.lowercased()
208	            guard !taken.contains(where: { $0.lowercased() == folded }),
209	                !FileManager.default.fileExists(atPath: url.path)
210	            else { return nil }
211	            taken.append(name)
212	            return .written
213	        }
214	    }
215	
216	    /// The copy: fonts, assets, then the module, none replacing a file; a throw removes what
217	    /// it wrote and rescans. One `rescan()` at the end. Main.
218	    func apply(to store: GraphicStore) throws {
219	        var written: [URL] = []
220	        var current = ""
221	        do {
222	            try store.ensureFolder()
223	            for (folder, places, files) in [
224	                (GraphicStore.fontsFolderName, fonts, contents.fonts),
225	                (GraphicStore.assetsFolderName, assets, contents.assets),
226	            ] {
227	                for (place, file) in zip(places, files) where place.action == .written {
228	                    current = "\(folder)/\(place.target)"
229	                    written.append(try store.landNew(file.bytes, into: folder, as: place.target))
230	                }
231	            }
232	            if module.action == .written {
233	                current = "\(module.target).js"
234	                try store.write(name: module.target, bytes: contents.source)
235	            }
236	        } catch {
237	            for url in written { try? FileManager.default.removeItem(at: url) }
238	            store.rescan()
239	            let why = (error as? ReelCoreError)?.message ?? error.localizedDescription
240	            throw ReelCoreError(message: "graphics/\(current) could not be written: \(why)")
241	        }
242	        store.rescan()
243	    }
244	
245	    /// `Imported <title> as <module>. Added: …. Already here: ….`
246	    var sentence: String {
247	        let all = [("\(module.target).js", module.action)]
248	            + fonts.map { ("\(GraphicStore.fontsFolderName)/\($0.target)", $0.action) }
249	            + assets.map { ("\(GraphicStore.assetsFolderName)/\($0.target)", $0.action) }
250	        var text = "Imported \(contents.title) as \(module.target)."
251	        for (label, action) in [("Added", GraphicImportAction.written), ("Already here", .reused)] {
252	            let names = all.filter { $0.1 == action }.map(\.0)
253	            if !names.isEmpty { text += " \(label): " + names.joined(separator: ", ") + "." }
254	        }
255	        return text
256	    }
257	
258	    /// `import_graphic`'s answer (spec §11 G-47 (i)).
259	    var reply: [String: Any] {
260	        var out: [String: Any] = [
261	            "name": module.target, "title": contents.title, "module": module.action.rawValue,
262	            "fonts": fonts.map { font -> [String: Any] in
263	                var row: [String: Any] = ["name": font.target, "action": font.action.rawValue]
264	                if font.target != font.name { row["renamed_from"] = font.name }
265	                return row
266	            },
267	            "assets": assets.map { ["name": $0.target, "action": $0.action.rawValue] },
268	            "note": AgentServer.notUndoableNote,
269	        ]
270	        if module.target != module.name { out["renamed_from"] = module.name }
271	        return out
272	    }
273	}
274	
275	extension ProjectDocument {
276	    /// Plans `contents` against this project and copies it in; the plan it carried out.
277	    func importGraphicPackage(_ contents: GraphicPackageContents) throws -> GraphicImportPlan {
278	        let plan = try GraphicImportPlan.make(contents, document: self)
279	        guard let store = graphicStore else {
280	            throw ReelCoreError(message: Self.noGraphicsFolderSentence)
281	        }
282	        try plan.apply(to: store)
283	        return plan
284	    }
285	}

