  1	// app/Sources/GraphicImportSheetController.swift — Import Graphic, the sheet
  2	// that asks before a `.fjgraphic` is copied into a project (spec §11 G-47
  3	// (f)), and the two doors that put it up: the Finder's (`open(packageAt:)`,
  4	// from `ProjectDocumentController`) and the Graphic dialog's From File…
  5	// (`ask(packageAt:editor:)`).
  6	//
  7	// **No second implementation.** The sheet shows a plan
  8	// (`GraphicImportPlan`, `GraphicPackageImport.swift`) and Import runs
  9	// `ProjectDocument.importGraphicPackage`, the body `import_graphic` calls,
 10	// which plans again against the folder as it is now. A throw beeps and shows
 11	// its sentence word for word in `graphicimport.message`, and the sheet stays.
 12	//
 13	// **What follows the sheet starts in `viewDidDisappear`**, for
 14	// `GraphicBrowserSheetController`'s reason: after Import, the Graphic dialog
 15	// opens on This Project with the module chosen and the import's sentence in
 16	// its message line. A sheet already attached to the window is queued by
 17	// AppKit's `beginSheet`.
 18	//
 19	// **The Finder door chooses its project once launch and restoration are
 20	// done** (G-47 (b)): `ProjectDocumentController.whenSettled`, then the front
 21	// project, else File ▸ New Project's untitled one. A package refused before
 22	// the sheet is an alert sheet on that project's window, or, with none,
 23	// `NSApp.presentError`, and opens no project.
 24	//
 25	// **The dev accept** (`-RCDevGraphicImportAccept YES`, dev tools only): the
 26	// sheet presses its own Import once it is up, so a proof can see a package
 27	// opened at launch land.
 28	
 29	import AppKit
 30	
 31	final class GraphicImportSheetController: NSViewController {
 32	    /// The dev-only launch default that presses Import (G-47's launch proof).
 33	    static let devAcceptKey = "RCDevGraphicImportAccept"
 34	
 35	    private let contents: GraphicPackageContents
 36	    private let plan: GraphicImportPlan
 37	    /// Weak, like every sheet's back-reference.
 38	    private weak var editor: EditorViewController?
 39	    private var imported: GraphicImportPlan?
 40	
 41	    private let messageLabel = NSTextField(wrappingLabelWithString: "")
 42	    private let importButton: NSButton
 43	    private static let width: CGFloat = 480
 44	
 45	    init(contents: GraphicPackageContents, plan: GraphicImportPlan, editor: EditorViewController) {
 46	        self.contents = contents
 47	        self.plan = plan
 48	        self.editor = editor
 49	        importButton = StickerButton(title: "Import", style: .primary, target: nil, action: nil)
 50	        super.init(nibName: nil, bundle: nil)
 51	    }
 52	
 53	    @available(*, unavailable)
 54	    required init?(coder: NSCoder) {
 55	        fatalError("GraphicImportSheetController does not support NSCoder")
 56	    }
 57	
 58	    // MARK: - The doors
 59	
 60	    /// The Finder's door: once launch and restoration are done, the package read, then the
 61	    /// front project (else a new untitled one) asked. Main.
 62	    static func open(packageAt url: URL) {
 63	        ProjectDocumentController.whenSettled {
 64	            let contents: GraphicPackageContents
 65	            do {
 66	                contents = try GraphicPackageContents.read(at: url)
 67	            } catch {
 68	                if let window = frontEditor()?.view.window {
 69	                    NSAlert(error: error).beginSheetModal(for: window, completionHandler: nil)
 70	                } else {
 71	                    NSApp.presentError(error)
 72	                }
 73	                return
 74	            }
 75	            guard let editor = frontEditor() ?? untitledEditor() else { return }
 76	            present(contents, editor: editor)
 77	        }
 78	    }
 79	
 80	    /// From File…'s door: the package read and asked about in `editor`'s project. Main.
 81	    static func ask(packageAt url: URL, editor: EditorViewController) {
 82	        do {
 83	            present(try GraphicPackageContents.read(at: url), editor: editor)
 84	        } catch {
 85	            alert(error, on: editor)
 86	        }
 87	    }
 88	
 89	    /// The first editor window front to back with a project, else the first of an open
 90	    /// project's (one restored but not yet ordered in).
 91	    static func frontEditor() -> EditorViewController? {
 92	        let editors = { (windows: [NSWindow]) in
 93	            windows.lazy.compactMap { $0.contentViewController as? EditorViewController }
 94	                .first { $0.document != nil }
 95	        }
 96	        let projects = NSDocumentController.shared.documents.compactMap { $0 as? ProjectDocument }
 97	        return editors(NSApp.orderedWindows)
 98	            ?? editors(projects.flatMap { $0.windowControllers.compactMap(\.window) })
 99	    }
100	
101	    /// File ▸ New Project's untitled project, made for the import; nil (the error shown) when
102	    /// it could not be made.
103	    private static func untitledEditor() -> EditorViewController? {
104	        do {
105	            let made = try NSDocumentController.shared.openUntitledDocumentAndDisplay(true)
106	            return made.windowControllers
107	                .compactMap { $0.contentViewController as? EditorViewController }.first
108	        } catch {
109	            NSApp.presentError(error)
110	            return nil
111	        }
112	    }
113	
114	    private static func present(_ contents: GraphicPackageContents, editor: EditorViewController) {
115	        guard let document = editor.document else {
116	            NSSound.beep()
117	            return
118	        }
119	        do {
120	            let plan = try GraphicImportPlan.make(contents, document: document)
121	            editor.presentAsSheet(
122	                GraphicImportSheetController(contents: contents, plan: plan, editor: editor))
123	        } catch {
124	            alert(error, on: editor)
125	        }
126	    }
127	
128	    private static func alert(_ error: Error, on editor: EditorViewController) {
129	        guard let window = editor.view.window else {
130	            NSSound.beep()
131	            return
132	        }
133	        NSAlert(error: error).beginSheetModal(for: window, completionHandler: nil)
134	    }
135	
136	    // MARK: - Layout
137	
138	    override func loadView() {
139	        let contentWidth = Self.width - sheetInset * 2
140	        let title = label(contents.title, id: "graphicimport.title", bold: true)
141	        let description = label(contents.description ?? "", id: "graphicimport.description")
142	        description.isHidden = contents.description == nil
143	        let module = label(Self.moduleLine(plan.module), id: "graphicimport.module")
144	        let fonts = label(
145	            Self.filesLine("Fonts", plan.fonts), id: "graphicimport.fonts")
146	        let assets = label(
147	            Self.filesLine("Pictures", plan.assets), id: "graphicimport.assets")
148	        let note = label(
149	            "Importing copies these files into this project's graphics. It is not an Undo step.",
150	            id: "graphicimport.footnote")
151	        note.textColor = DS.textMuted
152	        for field in [title, description, module, fonts, assets, note, messageLabel] {
153	            field.preferredMaxLayoutWidth = contentWidth
154	        }
155	        messageLabel.font = DS.sans(12)
156	        messageLabel.textColor = DS.textStrong
157	        messageLabel.setAccessibilityIdentifier("graphicimport.message")
158	
159	        importButton.target = self
160	        importButton.action = #selector(importClicked(_:))
161	        importButton.setAccessibilityIdentifier("graphicimport.import")
162	        let cancelButton = sheetCancelButton(target: self, action: #selector(cancelClicked(_:)))
163	        cancelButton.setAccessibilityIdentifier("graphicimport.cancel")
164	        view = makeSheetView(
165	            title: "Import Graphic",
166	            content: sheetColumn([title, description, module, fonts, assets, note, messageLabel]),
167	            buttonRow: makeButtonRow(cancel: cancelButton, apply: importButton),
168	            width: Self.width)
169	    }
170	
171	    private func label(_ text: String, id: String, bold: Bool = false) -> NSTextField {
172	        let field = NSTextField(wrappingLabelWithString: text)
173	        field.font = bold ? DS.sans(13, weight: .bold) : DS.sans(12)
174	        field.textColor = DS.textStrong
175	        field.setAccessibilityIdentifier(id)
176	        return field
177	    }
178	
179	    /// `Module: <m>`, `… (already in this project)`, or `Module: <target> (<m> is taken)`.
180	    static func moduleLine(_ place: GraphicImportPlacement) -> String {
181	        if place.action == .reused { return "Module: \(place.name) (already in this project)" }
182	        if place.target != place.name { return "Module: \(place.target) (\(place.name) is taken)" }
183	        return "Module: \(place.name)"
184	    }
185	
186	    /// `<heading>: a, b (already here), c (as c-2)`, or `<heading>: none`.
187	    static func filesLine(_ heading: String, _ places: [GraphicImportPlacement]) -> String {
188	        let names = places.map { place -> String in
189	            if place.action == .reused { return "\(place.name) (already here)" }
190	            if place.target != place.name { return "\(place.name) (as \(place.target))" }
191	            return place.name
192	        }
193	        return "\(heading): " + (names.isEmpty ? "none" : names.joined(separator: ", "))
194	    }
195	
196	    override func viewDidAppear() {
197	        super.viewDidAppear()
198	        #if FRAMEJOB_DEV_TOOLS
199	        if UserDefaults.standard.bool(forKey: Self.devAcceptKey) {
200	            DispatchQueue.main.async { [weak self] in self?.importClicked(nil) }
201	        }
202	        #endif
203	    }
204	
205	    // MARK: - Commit
206	
207	    @objc private func cancelClicked(_ sender: Any?) {
208	        dismiss(self)
209	    }
210	
211	    /// The import, once, against the folder as it is now. A throw beeps and shows its
212	    /// sentence, and the sheet stays; a success closes it.
213	    @objc private func importClicked(_ sender: Any?) {
214	        guard imported == nil, let document = editor?.document else {
215	            NSSound.beep()
216	            return
217	        }
218	        do {
219	            imported = try document.importGraphicPackage(contents)
220	        } catch {
221	            NSSound.beep()
222	            messageLabel.stringValue = (error as? ReelCoreError)?.message
223	                ?? error.localizedDescription
224	            return
225	        }
226	        dismiss(self)
227	    }
228	
229	    override func viewDidDisappear() {
230	        super.viewDidDisappear()
231	        guard let done = imported else { return }
232	        editor?.showGraphicBrowser(selecting: done.module.target, message: done.sentence)
233	    }
234	}

